import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import koffi from "koffi";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const FACE_FLOATS = 6 * 160 * 160;
const AUDIO_FLOATS = 20 * 256;
const PARAM_BIN_MAGIC = Buffer.from([0xdd, 0x85, 0x76, 0x00]);

function dllPath() {
  if (process.env.DUIX_NCNN_DLL) return process.env.DUIX_NCNN_DLL;
  return path.join(__dirname, "..", "native", "duix_ncnn.dll");
}

let api = null;
function loadApi() {
  if (api) return api;
  const file = dllPath();
  if (!fs.existsSync(file)) {
    throw new Error(`NCNN library not found: ${file}. Build js/duix-sdk/native/duix_ncnn.dll first.`);
  }
  const lib = koffi.load(file);
  api = {
    open: lib.func("void* duix_open(const char* param, const char* model, int binary)"),
    infer: lib.func("int duix_infer(void* net, const float* face, const float* audio, int audio_index, int face_index, int output_index, uint8_t* rgb)"),
    close: lib.func("void duix_close(void* net)"),
  };
  return api;
}

export class MunetEngine {
  constructor() {
    this.net = null;
    this.blobs = { audio: 0, face: 1, output: 180 };
    this.queue = Promise.resolve();
  }

  async init(paramPath, binPath, blobs = {}) {
    this.blobs = {
      audio: blobs.audio ?? 0,
      face: blobs.face ?? 1,
      output: blobs.output ?? 180,
    };
    const head = Buffer.alloc(4);
    const fd = fs.openSync(paramPath, "r");
    fs.readSync(fd, head, 0, 4, 0);
    fs.closeSync(fd);
    const binary = head.equals(PARAM_BIN_MAGIC) ? 1 : 0;
    const fn = loadApi();
    this.net = fn.open(paramPath, binPath, binary);
    if (!this.net) throw new Error(`failed to load NCNN model ${paramPath}`);
  }

  infer(faceChw, audio) {
    const run = this.queue.then(() => this._infer(faceChw, audio));
    this.queue = run.then(() => {}, () => {});
    return run;
  }

  _infer(faceChw, audio) {
    if (!this.net) throw new Error("munet is not initialized");
    if (faceChw.length !== FACE_FLOATS) throw new Error(`face length ${faceChw.length}`);
    if (audio.length < AUDIO_FLOATS) throw new Error(`audio length ${audio.length}`);
    const faceBuf = Buffer.from(faceChw.buffer, faceChw.byteOffset, FACE_FLOATS * 4);
    const audioBuf = Buffer.from(audio.buffer, audio.byteOffset, AUDIO_FLOATS * 4);
    const rgb = Buffer.alloc(160 * 160 * 3);
    const code = loadApi().infer(
      this.net,
      faceBuf,
      audioBuf,
      this.blobs.audio,
      this.blobs.face,
      this.blobs.output,
      rgb,
    );
    if (code !== 0) throw new Error(`munet infer failed: ${code}`);
    return new Uint8Array(rgb.buffer, rgb.byteOffset, rgb.byteLength);
  }

  close() {
    if (this.net) {
      loadApi().close(this.net);
      this.net = null;
    }
  }
}
